  perl -pe 's/.\x08//g'
}

extract_named_blocks() {
  local normalized_help_text="$1"

  printf '%s\n' "$normalized_help_text" \
    | awk '
        /^[A-Z][A-Z ]*COMMANDS$|^AVAILABLE COMMANDS$|^Commands:$|^Subcommands:$/ {in_block=1; next}
        in_block && /^[^[:space:]]/ {in_block=0}
        in_block {print}
      '
}

